 return{name:m.dragEvidence[i].name,scale:scales[i],target:targets[i],events:g.moves.length,lastMove:g.moves.at(-1),sourceCursor:pos,prediction,raw,expected:added,primaryMatches:added[0]?.x===prediction.x&&added[0]?.y===prediction.y};
});
